# Migration 0011 is an immutable, same-market temporal projection over the
# existing public orderbook and complement evidence.  It deliberately has no
# campaign, risk, order, execution, ledger, or settlement foreign keys.
orderbook_history_metadata = MetaData()
orderbook_history_analysis = Table(
    "orderbook_history_analysis",
    orderbook_history_metadata,
    Column("analysis_id", String(160), primary_key=True),
    Column("provider", String(30), nullable=False),
    Column("provider_market_ticker", String(300), nullable=False),
    Column("history_evaluator_version", String(80), nullable=False),
    Column(
        "first_orderbook_snapshot_id",
        String(160),
        ForeignKey(market_orderbook_snapshot.c.orderbook_snapshot_id),
        nullable=False,
    ),
    Column(
        "last_orderbook_snapshot_id",
        String(160),
        ForeignKey(market_orderbook_snapshot.c.orderbook_snapshot_id),
        nullable=False,
    ),
    Column("requested_maximum_observation_count", Integer, nullable=False),
    Column("included_observation_count", Integer, nullable=False),
    Column("candidate_observation_count", Integer, nullable=False),
    Column("no_candidate_observation_count", Integer, nullable=False),
    Column("ineligible_observation_count", Integer, nullable=False),
    Column("invalid_observation_count", Integer, nullable=False),
    Column("continuity_segment_count", Integer, nullable=False),
    Column("evidence_break_count", Integer, nullable=False),
    Column("observation_gap_count", Integer, nullable=False),
    Column("current_candidate_streak_observation_count", Integer, nullable=False),
    Column("longest_candidate_streak_observation_count", Integer, nullable=False),
    Column("current_candidate_streak_duration", sa.Interval(), nullable=True),
    Column("longest_candidate_streak_duration", sa.Interval(), nullable=True),
    Column("first_candidate_observed_at", DateTime(timezone=True), nullable=True),
    Column("latest_candidate_observed_at", DateTime(timezone=True), nullable=True),
    Column("current_matched_quantity", DECIMAL_TYPE, nullable=True),
    Column("maximum_compatible_matched_quantity", DECIMAL_TYPE, nullable=True),
    Column("current_conservative_net_lower_bound", DECIMAL_TYPE, nullable=True),
    Column("maximum_compatible_conservative_net_lower_bound", DECIMAL_TYPE, nullable=True),
    Column("minimum_lower_bound_current_streak", DECIMAL_TYPE, nullable=True),
    Column("current_net_lower_bound_per_contract", DECIMAL_TYPE, nullable=True),
    Column("maximum_observation_gap", sa.Interval(), nullable=False),
    Column("continuity_gap_threshold", sa.Interval(), nullable=False),
    Column("state", String(20), nullable=False),
    Column("canonical_configuration_hash", String(HASH_LENGTH), nullable=False),
    Column("canonical_input_hash", String(HASH_LENGTH), nullable=False),
    Column("canonical_result_hash", String(HASH_LENGTH), nullable=False),
    Column("created_at", DateTime(timezone=True), nullable=False),
    CheckConstraint("provider = 'KALSHI'", name="ck_orderbook_history_analysis_provider"),
    CheckConstraint(
        "requested_maximum_observation_count BETWEEN 3 AND 50 "
        "AND included_observation_count BETWEEN 3 AND requested_maximum_observation_count",
        name="ck_orderbook_history_analysis_observation_count",
    ),
    CheckConstraint(
        "candidate_observation_count >= 0 AND no_candidate_observation_count >= 0 "
        "AND ineligible_observation_count >= 0 AND invalid_observation_count >= 0 "
        "AND continuity_segment_count >= 0 AND evidence_break_count >= 0 "
        "AND observation_gap_count >= 0 AND current_candidate_streak_observation_count >= 0 "
        "AND longest_candidate_streak_observation_count >= 0",
        name="ck_orderbook_history_analysis_counts",
    ),
    CheckConstraint(
        "candidate_observation_count + no_candidate_observation_count "
        "+ ineligible_observation_count + invalid_observation_count = included_observation_count",
        name="ck_orderbook_history_analysis_state_counts",
    ),
    CheckConstraint(
        "state IN ('COMPLETE', 'PARTIAL', 'INVALID')",
        name="ck_orderbook_history_analysis_state",
    ),
    CheckConstraint(
        "length(canonical_configuration_hash) = 64 AND length(canonical_input_hash) = 64 "
        "AND length(canonical_result_hash) = 64",
        name="ck_orderbook_history_analysis_hashes",
    ),
)
