# Migration 0012 adds one mutable foreground-session root and append-only
# observation records.  It references only the isolated public-evidence graph.
capture_metadata = MetaData()
orderbook_capture_session = Table(
    "orderbook_capture_session",
    capture_metadata,
    Column("session_id", String(160), primary_key=True),
    Column(
        "evidence_ingestion_run_id",
        String(160),
        ForeignKey(provider_ingestion_run.c.ingestion_run_id),
        nullable=False,
    ),
    Column("provider", String(30), nullable=False),
    Column("provider_market_ticker", String(300), nullable=False),
    Column(
        "market_snapshot_id",
        String(160),
        ForeignKey(normalized_market_snapshot.c.snapshot_id),
        nullable=False,
    ),
    Column(
        "market_raw_response_id", String(160), ForeignKey(raw_provider_response.c.raw_response_id)
    ),
    Column("requested_observation_count", Integer, nullable=False),
    Column("requested_interval_seconds", Integer, nullable=False),
    Column("requested_depth", Integer, nullable=False),
    Column("requested_maximum_bundle_quantity", DECIMAL_TYPE, nullable=False),
    Column("request_timeout_seconds", Integer, nullable=False),
    Column("maximum_duration", sa.Interval(), nullable=False),
    Column("started_at", DateTime(timezone=True), nullable=False),
    Column("completed_at", DateTime(timezone=True)),
    Column("state", String(20), nullable=False),
    Column("attempted_observation_count", Integer, nullable=False),
    Column("successful_observation_count", Integer, nullable=False),
    Column("failed_observation_count", Integer, nullable=False),
    Column("first_successful_observed_at", DateTime(timezone=True)),
    Column("last_successful_observed_at", DateTime(timezone=True)),
    Column(
        "history_analysis_id", String(160), ForeignKey(orderbook_history_analysis.c.analysis_id)
    ),
    Column("canonical_configuration_hash", String(HASH_LENGTH), nullable=False),
    Column("canonical_input_hash", String(HASH_LENGTH), nullable=False),
    Column("canonical_result_hash", String(HASH_LENGTH)),
    Column("created_at", DateTime(timezone=True), nullable=False),
    Column("last_error_code", String(120)),
    CheckConstraint("provider = 'KALSHI'", name="ck_orderbook_capture_session_provider"),
    CheckConstraint(
        "requested_observation_count BETWEEN 3 AND 20",
        name="ck_orderbook_capture_session_observations",
    ),
    CheckConstraint(
        "requested_interval_seconds BETWEEN 5 AND 300", name="ck_orderbook_capture_session_interval"
    ),
    CheckConstraint("requested_depth BETWEEN 1 AND 20", name="ck_orderbook_capture_session_depth"),
    CheckConstraint(
        "requested_maximum_bundle_quantity > 0 AND requested_maximum_bundle_quantity <= 100",
        name="ck_orderbook_capture_session_quantity",
    ),
    CheckConstraint(
        "request_timeout_seconds BETWEEN 1 AND 30", name="ck_orderbook_capture_session_timeout"
    ),
    CheckConstraint(
        "state IN ('CREATED', 'RUNNING', 'COMPLETED', 'FAILED', 'INTERRUPTED')",
        name="ck_orderbook_capture_session_state",
    ),
    CheckConstraint(
        "attempted_observation_count >= 0 AND successful_observation_count >= 0 "
        "AND failed_observation_count >= 0 AND successful_observation_count "
        "+ failed_observation_count = attempted_observation_count",
        name="ck_orderbook_capture_session_counts",
    ),
    CheckConstraint(
        "length(canonical_configuration_hash) = 64 AND length(canonical_input_hash) = 64 "
        "AND (canonical_result_hash IS NULL OR length(canonical_result_hash) = 64)",
        name="ck_orderbook_capture_session_hashes",
    ),
)
