# Migration 0013 adds an immutable, public-only threshold relationship overlay.
# It reuses retained market, raw, fee, and orderbook evidence and never reaches
# campaign, ledger, order, risk, execution, position, or settlement tables.
threshold_ladder_metadata = MetaData()
threshold_ladder_scan = Table(
    "threshold_ladder_scan",
    threshold_ladder_metadata,
    Column("scan_id", String(160), primary_key=True),
    Column(
        "evidence_ingestion_run_id",
        String(160),
        ForeignKey(provider_ingestion_run.c.ingestion_run_id),
        nullable=False,
        unique=True,
    ),
    Column("provider", String(30), nullable=False),
    Column("requested_event_count", Integer, nullable=False),
    Column("selected_event_count", Integer, nullable=False),
    Column("maximum_markets_per_event", Integer, nullable=False),
    Column("rounds_requested", Integer, nullable=False),
    Column("interval_seconds", Integer, nullable=False),
    Column("maximum_depth", Integer, nullable=False),
    Column("maximum_bundle_quantity", DECIMAL_TYPE, nullable=False),
    Column("maximum_observation_skew", sa.Interval(), nullable=False),
    Column("timeout_seconds", Integer, nullable=False),
    Column("started_at", DateTime(timezone=True), nullable=False),
    Column("completed_at", DateTime(timezone=True), nullable=True),
    Column("state", String(20), nullable=False),
    Column("relationship_count", Integer, nullable=False),
    Column("evaluation_count", Integer, nullable=False),
    Column("candidate_count", Integer, nullable=False),
    Column("persisting_candidate_count", Integer, nullable=False),
    Column("canonical_configuration_hash", String(HASH_LENGTH), nullable=False),
    Column("canonical_input_hash", String(HASH_LENGTH), nullable=False),
    Column("canonical_result_hash", String(HASH_LENGTH), nullable=True),
    Column("last_error_code", String(120), nullable=True),
    Column("created_at", DateTime(timezone=True), nullable=False),
    CheckConstraint("provider = 'KALSHI'", name="ck_threshold_ladder_scan_provider"),
    CheckConstraint(
        "requested_event_count BETWEEN 1 AND 10 "
        "AND selected_event_count BETWEEN 0 AND requested_event_count",
        name="ck_threshold_ladder_scan_event_counts",
    ),
    CheckConstraint(
        "maximum_markets_per_event BETWEEN 2 AND 12 AND rounds_requested BETWEEN 2 AND 5 "
        "AND interval_seconds BETWEEN 5 AND 60 AND maximum_depth BETWEEN 1 AND 20 "
        "AND maximum_bundle_quantity > 0 AND maximum_bundle_quantity <= 100 "
        "AND maximum_observation_skew BETWEEN interval '1 second' AND interval '15 seconds' "
        "AND timeout_seconds BETWEEN 1 AND 30",
        name="ck_threshold_ladder_scan_bounds",
    ),
    CheckConstraint(
        "state IN ('RUNNING', 'COMPLETED', 'PARTIAL', 'FAILED', 'INTERRUPTED')",
        name="ck_threshold_ladder_scan_state",
    ),
    CheckConstraint(
        "relationship_count >= 0 AND evaluation_count >= 0 AND candidate_count >= 0 "
        "AND persisting_candidate_count >= 0",
        name="ck_threshold_ladder_scan_counts",
    ),
    CheckConstraint(
        "length(canonical_configuration_hash) = 64 AND length(canonical_input_hash) = 64 "
        "AND (canonical_result_hash IS NULL OR length(canonical_result_hash) = 64)",
        name="ck_threshold_ladder_scan_hashes",
    ),
)
