# Migration 0021 adds finite, local worker-owned SHADOW operations.  These
# records are deliberately separate from campaigns' financial rows: a plan can
# retain public evidence and score forecasts, but cannot create an order,
# reservation, position, journal, or settlement fact.
shadow_operations_metadata = MetaData()
Table("campaign", shadow_operations_metadata, Column("campaign_id", String(160), primary_key=True))
Table(
    "shadow_prediction",
    shadow_operations_metadata,
    Column("prediction_id", String(160), primary_key=True),
)
shadow_evidence_plan = Table(
    "shadow_evidence_plan",
    shadow_operations_metadata,
    Column("plan_id", String(160), primary_key=True),
    Column("campaign_id", String(160), ForeignKey("campaign.campaign_id"), nullable=False),
    Column("name", String(160), nullable=False),
    Column("state", String(20), nullable=False),
    Column("iterations_requested", Integer, nullable=False),
    Column("interval_seconds", Integer, nullable=False),
    Column("maximum_duration_seconds", Integer, nullable=False),
    Column("market_count", Integer, nullable=False),
    Column("maximum_pages", Integer, nullable=False),
    Column("maximum_enrichments", Integer, nullable=False),
    Column("maximum_markets_per_event", Integer, nullable=False),
    Column("maximum_markets_per_series", Integer, nullable=False),
    Column("orderbook_depth", Integer, nullable=False),
    Column("maximum_predictions_per_iteration", Integer, nullable=False),
    Column("maximum_opportunities_per_iteration", Integer, nullable=False),
    Column("timeout_seconds", Integer, nullable=False),
    Column("strategy_ids", ARRAY(Text), nullable=False),
    Column("strategy_configuration_hashes_payload", Text, nullable=False),
    Column("policy_identity", String(160), nullable=False),
    Column("policy_hash", String(HASH_LENGTH), nullable=False),
    Column("operator_note", String(500), nullable=False),
    Column("idempotency_key", String(160), nullable=False),
    Column("created_at", DateTime(timezone=True), nullable=False),
    Column("started_at", DateTime(timezone=True)),
    Column("paused_at", DateTime(timezone=True)),
    Column("completed_at", DateTime(timezone=True)),
    Column("next_due_at", DateTime(timezone=True), nullable=False),
    Column("completed_iterations", Integer, nullable=False),
    Column("partial_iterations", Integer, nullable=False),
    Column("failed_iterations", Integer, nullable=False),
    Column("last_completed_stage", String(120)),
    Column("last_error_code", String(160)),
    Column("last_action_reason", String(500)),
    Column("canonical_request_hash", String(HASH_LENGTH), nullable=False),
    Column("canonical_result_hash", String(HASH_LENGTH)),
    Column("created_at_version", String(40), nullable=False),
    UniqueConstraint("campaign_id", "idempotency_key"),
    CheckConstraint(
        "state IN ('CREATED', 'RUNNING', 'PAUSED', 'COMPLETED', 'PARTIAL', "
        "'FAILED', 'CANCELED', 'INTERRUPTED')",
        name="ck_shadow_evidence_plan_state",
    ),
    CheckConstraint(
        "iterations_requested BETWEEN 3 AND 288", name="ck_shadow_evidence_plan_iterations"
    ),
    CheckConstraint(
        "interval_seconds BETWEEN 30 AND 86400", name="ck_shadow_evidence_plan_interval"
    ),
    CheckConstraint(
        "maximum_duration_seconds = iterations_requested * interval_seconds "
        "AND maximum_duration_seconds BETWEEN 90 AND 2592000",
        name="ck_shadow_evidence_plan_duration",
    ),
    CheckConstraint("market_count BETWEEN 3 AND 50", name="ck_shadow_evidence_plan_market_count"),
    CheckConstraint("maximum_pages BETWEEN 1 AND 5", name="ck_shadow_evidence_plan_pages"),
    CheckConstraint(
        "maximum_enrichments BETWEEN market_count AND 80",
        name="ck_shadow_evidence_plan_enrichments",
    ),
    CheckConstraint(
        "maximum_markets_per_event BETWEEN 1 AND 5",
        name="ck_shadow_evidence_plan_per_event",
    ),
    CheckConstraint(
        "maximum_markets_per_series BETWEEN 1 AND 10",
        name="ck_shadow_evidence_plan_per_series",
    ),
    CheckConstraint("orderbook_depth BETWEEN 1 AND 20", name="ck_shadow_evidence_plan_depth"),
    CheckConstraint(
        "maximum_predictions_per_iteration BETWEEN 1 AND 500 "
        "AND maximum_opportunities_per_iteration BETWEEN 1 AND 500",
        name="ck_shadow_evidence_plan_output_bounds",
    ),
    CheckConstraint("timeout_seconds BETWEEN 1 AND 60", name="ck_shadow_evidence_plan_timeout"),
    CheckConstraint(
        "completed_iterations >= 0 AND partial_iterations >= 0 AND failed_iterations >= 0 "
        "AND completed_iterations + partial_iterations + failed_iterations <= iterations_requested",
        name="ck_shadow_evidence_plan_counts",
    ),
    CheckConstraint(
        "length(policy_hash) = 64 AND length(canonical_request_hash) = 64 "
        "AND (canonical_result_hash IS NULL OR length(canonical_result_hash) = 64)",
        name="ck_shadow_evidence_plan_hashes",
    ),
)
