    Column("fee_lineage_hash", String(HASH_LENGTH)),
    Column("state", String(20), nullable=False),
    Column("inactive_at", DateTime(timezone=True)),
    Column("reason_codes", ARRAY(Text), nullable=False),
    Column("enrichment_hash", String(HASH_LENGTH), nullable=False),
