# Migration 0022 adds independently inspectable, immutable evidence-review
# packets and a campaign-scoped PAPER trial overlay.  These tables do not own
# money, orders, or positions; immutable lineage rows refer to the established
# financial authorities instead of widening them.
evidence_review_metadata = MetaData()
Table("campaign", evidence_review_metadata, Column("campaign_id", String(160), primary_key=True))
Table(
    "strategy_governance",
    evidence_review_metadata,
    Column("strategy_id", String(160), primary_key=True),
    Column("version", String(160), primary_key=True),
)
Table(
    "paper_execution_policy",
    evidence_review_metadata,
    Column("policy_version_id", String(160), primary_key=True),
)
Table(
    "operator_action", evidence_review_metadata, Column("action_id", String(160), primary_key=True)
)
Table(
    "autopilot_cycle", evidence_review_metadata, Column("cycle_id", String(160), primary_key=True)
)
Table(
    "opportunity_assessment",
    evidence_review_metadata,
    Column("assessment_id", String(160), primary_key=True),
)
Table(
    "risk_decision",
    evidence_review_metadata,
    Column("risk_decision_id", String(160), primary_key=True),
)
Table(
    "risk_reservation",
    evidence_review_metadata,
    Column("reservation_id", String(160), primary_key=True),
)
Table("order", evidence_review_metadata, Column("order_id", String(160), primary_key=True))
Table("position", evidence_review_metadata, Column("position_id", String(160), primary_key=True))

strategy_evidence_review_policy = Table(
    "strategy_evidence_review_policy",
    evidence_review_metadata,
    Column("policy_id", String(160), primary_key=True),
    Column("policy_version", String(160), primary_key=True),
    Column("supported_strategy_family", String(40)),
    Column("supported_strategy_id", String(160)),
    Column("minimum_resolved_predictions", Integer, nullable=False),
    Column("minimum_distinct_events", Integer, nullable=False),
    Column("minimum_distinct_markets", Integer, nullable=False),
    Column("minimum_probability_range_coverage", Integer, nullable=False),
    Column("maximum_unresolved_integrity_warnings", Integer, nullable=False),
    Column("maximum_point_brier_difference", DECIMAL_TYPE, nullable=False),
    Column("maximum_conservative_brier_difference", DECIMAL_TYPE, nullable=False),
    Column("maximum_point_log_loss_difference", DECIMAL_TYPE, nullable=False),
    Column("maximum_conservative_log_loss_difference", DECIMAL_TYPE, nullable=False),
    Column("maximum_recent_degradation", DECIMAL_TYPE, nullable=False),
    Column("minimum_recent_resolved", Integer, nullable=False),
    Column("minimum_calibration_coverage", DECIMAL_TYPE, nullable=False),
    Column("maximum_conflict_frequency", DECIMAL_TYPE, nullable=False),
    Column("maximum_evidence_age_seconds", Integer, nullable=False),
    Column("require_configuration_lineage", Boolean, nullable=False),
    Column("require_outcome_lineage", Boolean, nullable=False),
    Column("configuration_hash", String(HASH_LENGTH), nullable=False),
    Column("created_at", DateTime(timezone=True), nullable=False),
    Column("superseded_at", DateTime(timezone=True)),
    Column("canonical_payload_hash", String(HASH_LENGTH), nullable=False),
    CheckConstraint(
        "(supported_strategy_family IS NULL) <> (supported_strategy_id IS NULL)",
        name="ck_evidence_review_policy_scope",
    ),
    CheckConstraint(
        "minimum_resolved_predictions > 0 AND minimum_distinct_events > 0 "
        "AND minimum_distinct_markets > 0 AND minimum_probability_range_coverage BETWEEN 1 AND 5 "
        "AND maximum_unresolved_integrity_warnings >= 0 AND minimum_recent_resolved > 0",
        name="ck_evidence_review_policy_counts",
    ),
    CheckConstraint(
        "maximum_point_brier_difference >= 0 AND maximum_conservative_brier_difference >= 0 "
        "AND maximum_point_log_loss_difference >= 0 AND maximum_conservative_log_loss_difference >= 0 "
        "AND maximum_recent_degradation >= 0 AND minimum_calibration_coverage BETWEEN 0 AND 1 "
        "AND maximum_conflict_frequency BETWEEN 0 AND 1 AND maximum_evidence_age_seconds > 0",
        name="ck_evidence_review_policy_metrics",
    ),
    CheckConstraint(
        "length(configuration_hash) = 64 AND length(canonical_payload_hash) = 64",
        name="ck_evidence_review_policy_hashes",
    ),
)
