# Migration 0023 adds a research-only learning ledger.  It deliberately has no
# foreign keys to campaign, order, position, reservation, or financial tables:
# a model candidate is evidence for human review, never operational authority.
strategy_lab_metadata = MetaData()
strategy_lab_feature_schema = Table(
    "strategy_lab_feature_schema",
    strategy_lab_metadata,
    Column("schema_id", String(160), primary_key=True),
    Column("vertical", String(80), nullable=False),
    Column("research_family", String(160), nullable=False),
    Column("schema_version", String(80), nullable=False),
    Column("feature_definitions_payload", Text, nullable=False),
    Column("feature_names", ARRAY(Text), nullable=False),
    Column("created_at", DateTime(timezone=True), nullable=False),
    Column("superseded_at", DateTime(timezone=True)),
    Column("canonical_payload", Text, nullable=False),
    Column("canonical_hash", String(HASH_LENGTH), nullable=False, unique=True),
    UniqueConstraint("vertical", "research_family", "schema_version"),
    CheckConstraint(
        "cardinality(feature_names) BETWEEN 1 AND 32", name="ck_strategy_lab_schema_features"
    ),
    CheckConstraint("length(canonical_hash) = 64", name="ck_strategy_lab_schema_hash"),
)
