    Column("canonical_hash", String(HASH_LENGTH), nullable=False, unique=True),
    UniqueConstraint("vertical", "research_family", "label_version"),
    CheckConstraint("target_type = 'BINARY_PROBABILITY'", name="ck_strategy_lab_label_target"),
    CheckConstraint("length(canonical_hash) = 64", name="ck_strategy_lab_label_hash"),
