# Migration 0025 adds an immutable, research-only continuous-market evidence
# ledger.  The campaign reference is read only; none of these tables references
# financial orders, reservations, positions, settlements, journals, or postings.
securities_metadata = MetaData()
Table("campaign", securities_metadata, Column("campaign_id", String(160), primary_key=True))
securities_instrument = Table(
    "securities_instrument",
    securities_metadata,
    Column("instrument_id", String(160), primary_key=True),
    Column("symbol", String(32), nullable=False),
    Column("asset_class", String(30), nullable=False),
    Column("exchange_mic", String(12), nullable=False),
    Column("currency", String(3), nullable=False),
    Column("timezone", String(80), nullable=False),
    Column("valid_from", String(10), nullable=False),
    Column("valid_to", String(10)),
    Column("source_identity", String(240), nullable=False),
    Column("content_hash", String(HASH_LENGTH), nullable=False, unique=True),
    CheckConstraint(
        "asset_class IN ('COMMON_STOCK','ETF')",
        name="ck_securities_instrument_asset_class",
    ),
    CheckConstraint("currency = 'USD'", name="ck_securities_instrument_currency"),
    CheckConstraint("length(content_hash) = 64", name="ck_securities_instrument_hash"),
)
securities_market_data_batch = Table(
    "securities_market_data_batch",
    securities_metadata,
    Column("batch_id", String(160), primary_key=True),
    Column("dataset_name", String(160), nullable=False),
    Column("state", String(20), nullable=False),
    Column("imported_at", DateTime(timezone=True), nullable=False),
    Column("source_artifact", String(500), nullable=False),
    Column("source_sha256", String(HASH_LENGTH), nullable=False),
    Column("source_byte_size", Integer, nullable=False),
    Column("canonical_artifact", String(500), nullable=False),
    Column("canonical_sha256", String(HASH_LENGTH), nullable=False),
    Column("canonical_byte_size", Integer, nullable=False),
    Column("instrument_count", Integer, nullable=False),
    Column("session_count", Integer, nullable=False),
    Column("bar_count", Integer, nullable=False),
    Column("corporate_action_count", Integer, nullable=False),
    Column("first_period_start", DateTime(timezone=True), nullable=False),
    Column("last_period_end", DateTime(timezone=True), nullable=False),
    Column("idempotency_key", String(160), nullable=False, unique=True),
    Column("warnings", ARRAY(Text), nullable=False),
    Column("canonical_hash", String(HASH_LENGTH), nullable=False),
    CheckConstraint("state IN ('READY','REJECTED')", name="ck_securities_batch_state"),
    CheckConstraint(
        "source_byte_size > 0 AND canonical_byte_size > 0 "
        "AND instrument_count > 0 AND session_count > 0 AND bar_count > 0 "
        "AND corporate_action_count >= 0",
        name="ck_securities_batch_counts",
    ),
    CheckConstraint(
        "length(source_sha256) = 64 AND length(canonical_sha256) = 64 "
        "AND length(canonical_hash) = 64",
        name="ck_securities_batch_hashes",
    ),
)
securities_calendar_session = Table(
    "securities_calendar_session",
    securities_metadata,
    Column(
        "batch_id",
        String(160),
        ForeignKey("securities_market_data_batch.batch_id"),
        primary_key=True,
    ),
    Column("session_id", String(160), primary_key=True),
    Column("calendar_identity", String(120), nullable=False),
    Column("calendar_version", String(80), nullable=False),
    Column("timezone", String(80), nullable=False),
    Column("session_date", String(10), nullable=False),
    Column("opens_at", DateTime(timezone=True), nullable=False),
    Column("closes_at", DateTime(timezone=True), nullable=False),
    Column("is_early_close", Boolean, nullable=False),
    Column("source_identity", String(240), nullable=False),
    Column("content_hash", String(HASH_LENGTH), nullable=False),
    UniqueConstraint("batch_id", "calendar_identity", "session_date"),
    CheckConstraint("opens_at < closes_at", name="ck_securities_session_window"),
    CheckConstraint("length(content_hash) = 64", name="ck_securities_session_hash"),
)
securities_bar_evidence = Table(
    "securities_bar_evidence",
    securities_metadata,
    Column(
        "batch_id",
        String(160),
        ForeignKey("securities_market_data_batch.batch_id"),
        primary_key=True,
    ),
    Column("bar_id", String(160), primary_key=True),
    Column(
        "instrument_id",
        String(160),
        ForeignKey("securities_instrument.instrument_id"),
        nullable=False,
    ),
    Column("interval", String(20), nullable=False),
    Column("adjustment_state", String(30), nullable=False),
    Column("period_start", DateTime(timezone=True), nullable=False),
    Column("period_end", DateTime(timezone=True), nullable=False),
    Column("available_at", DateTime(timezone=True), nullable=False),
    Column("open", DECIMAL_TYPE, nullable=False),
    Column("high", DECIMAL_TYPE, nullable=False),
    Column("low", DECIMAL_TYPE, nullable=False),
    Column("close", DECIMAL_TYPE, nullable=False),
    Column("volume", DECIMAL_TYPE, nullable=False),
    Column("source_identity", String(240), nullable=False),
    Column("content_hash", String(HASH_LENGTH), nullable=False),
    UniqueConstraint(
        "batch_id",
        "instrument_id",
        "interval",
        "adjustment_state",
        "period_start",
    ),
    CheckConstraint("interval IN ('ONE_DAY','ONE_HOUR')", name="ck_securities_bar_interval"),
    CheckConstraint(
        "adjustment_state IN ('RAW','SPLIT_ADJUSTED','TOTAL_RETURN_ADJUSTED')",
        name="ck_securities_bar_adjustment",
    ),
    CheckConstraint(
        "period_start < period_end AND available_at >= period_end",
        name="ck_securities_bar_timing",
    ),
    CheckConstraint(
        "open > 0 AND high > 0 AND low > 0 AND close > 0 AND volume >= 0 "
        "AND low <= open AND low <= close AND high >= open AND high >= close "
        "AND low <= high",
        name="ck_securities_bar_ohlcv",
    ),
    CheckConstraint("length(content_hash) = 64", name="ck_securities_bar_hash"),
)
securities_corporate_action_evidence = Table(
    "securities_corporate_action_evidence",
    securities_metadata,
    Column(
        "batch_id",
        String(160),
        ForeignKey("securities_market_data_batch.batch_id"),
        primary_key=True,
    ),
    Column("action_id", String(160), primary_key=True),
    Column(
        "instrument_id",
        String(160),
        ForeignKey("securities_instrument.instrument_id"),
        nullable=False,
    ),
    Column("action_type", String(30), nullable=False),
    Column("effective_date", String(10), nullable=False),
    Column("available_at", DateTime(timezone=True), nullable=False),
    Column("split_ratio", DECIMAL_TYPE),
    Column("cash_amount", DECIMAL_TYPE),
    Column("successor_symbol", String(32)),
    Column("source_identity", String(240), nullable=False),
    Column("content_hash", String(HASH_LENGTH), nullable=False),
    CheckConstraint(
        "action_type IN ('SPLIT','CASH_DIVIDEND','SYMBOL_CHANGE','DELISTING')",
        name="ck_securities_action_type",
    ),
    CheckConstraint(
        "(action_type = 'SPLIT' AND split_ratio > 0 AND cash_amount IS NULL "
        "AND successor_symbol IS NULL) OR "
        "(action_type = 'CASH_DIVIDEND' AND split_ratio IS NULL "
        "AND cash_amount >= 0 AND successor_symbol IS NULL) OR "
        "(action_type = 'SYMBOL_CHANGE' AND split_ratio IS NULL "
        "AND cash_amount IS NULL AND successor_symbol IS NOT NULL) OR "
        "(action_type = 'DELISTING' AND split_ratio IS NULL "
        "AND cash_amount IS NULL AND successor_symbol IS NULL)",
        name="ck_securities_action_fields",
    ),
    CheckConstraint("length(content_hash) = 64", name="ck_securities_action_hash"),
)
securities_strategy_specification = Table(
    "securities_strategy_specification",
    securities_metadata,
    Column("specification_id", String(160), primary_key=True),
    Column("strategy_id", String(160), nullable=False, unique=True),
    Column("kind", String(40), nullable=False),
    Column("version", String(80), nullable=False),
    Column("interval", String(20), nullable=False),
    Column("adjustment_state", String(30), nullable=False),
    Column("lookback_sessions", Integer, nullable=False),
    Column("rebalance_every_sessions", Integer, nullable=False),
    Column("top_quantile", DECIMAL_TYPE, nullable=False),
    Column("allow_research_short", Boolean, nullable=False),
    Column("estimated_cost_bps", DECIMAL_TYPE, nullable=False),
    Column("strategy_lab_deployment_id", String(160)),
    Column("created_at", DateTime(timezone=True), nullable=False),
    Column("canonical_payload", Text, nullable=False),
    Column("canonical_hash", String(HASH_LENGTH), nullable=False, unique=True),
    CheckConstraint(
        "kind IN ('CASH_BASELINE','BUY_AND_HOLD','TIME_SERIES_MOMENTUM',"
        "'CROSS_SECTIONAL_MOMENTUM','STRATEGY_LAB_MODEL')",
        name="ck_securities_spec_kind",
    ),
    CheckConstraint(
        "lookback_sessions BETWEEN 1 AND 252 "
        "AND rebalance_every_sessions BETWEEN 1 AND 63 "
        "AND top_quantile > 0 AND top_quantile <= 1 "
        "AND estimated_cost_bps >= 0 AND estimated_cost_bps <= 100",
        name="ck_securities_spec_bounds",
    ),
    CheckConstraint(
        "(kind = 'STRATEGY_LAB_MODEL' AND strategy_lab_deployment_id IS NOT NULL) "
        "OR (kind <> 'STRATEGY_LAB_MODEL' AND strategy_lab_deployment_id IS NULL)",
        name="ck_securities_spec_model_binding",
    ),
    CheckConstraint("length(canonical_hash) = 64", name="ck_securities_spec_hash"),
)
