# Migration 0028 adds a research-only governance overlay over existing Strategy
# Lab and Securities result identities.  It intentionally has no foreign keys
# into campaigns, capital, orders, positions, settlements, or the ledger.
research_integrity_metadata = MetaData()
research_experiment_family = Table(
    "research_experiment_family",
    research_integrity_metadata,
    Column("experiment_id", String(160), primary_key=True),
    Column("name", String(240), nullable=False),
    Column("vertical", String(80), nullable=False),
    Column("research_family", String(160), nullable=False),
    Column("research_question", Text, nullable=False),
    Column("target_label_identity", String(240), nullable=False),
    Column("benchmark_identities", ARRAY(Text), nullable=False),
    Column("data_scope_identities", ARRAY(Text), nullable=False),
    Column("data_scope_hashes", ARRAY(String(HASH_LENGTH)), nullable=False),
    Column("universe_hash", String(HASH_LENGTH), nullable=False),
    Column("period_start", String(40), nullable=False),
    Column("period_end", String(40), nullable=False),
    Column("cutoff_at", DateTime(timezone=True), nullable=False),
    Column("feature_schema_hashes", ARRAY(String(HASH_LENGTH)), nullable=False),
    Column("permitted_families", ARRAY(Text), nullable=False),
    Column("parameter_space_payload", Text, nullable=False),
    Column("parameter_space_hash", String(HASH_LENGTH), nullable=False),
    Column("maximum_trials", Integer, nullable=False),
    Column("maximum_feature_variants", Integer, nullable=False),
    Column("maximum_model_variants", Integer, nullable=False),
    Column("maximum_simulator_variants", Integer, nullable=False),
    Column("evaluation_policy_id", String(160), nullable=False),
    Column("evaluation_policy_hash", String(HASH_LENGTH), nullable=False),
    Column("cost_execution_assumptions", Text, nullable=False),
    Column("cost_execution_hash", String(HASH_LENGTH), nullable=False),
    Column("frequency", String(30), nullable=False),
    Column("state", String(20), nullable=False),
    Column("created_at", DateTime(timezone=True), nullable=False),
    Column("opened_at", DateTime(timezone=True)),
    Column("closed_at", DateTime(timezone=True)),
    Column("operator_action_id", String(160), nullable=False),
    Column("operator_reason", String(500), nullable=False),
    Column("idempotency_key", String(160), nullable=False, unique=True),
    Column("canonical_input_hash", String(HASH_LENGTH), nullable=False, unique=True),
    Column("canonical_result_hash", String(HASH_LENGTH), nullable=False),
    CheckConstraint(
        "state IN ('DRAFT','OPEN','CLOSED','CANCELED','INVALIDATED') "
        "AND frequency IN ('DAILY','EVENT_RESOLUTION')",
        name="ck_research_experiment_state_frequency",
    ),
    CheckConstraint(
        "maximum_trials BETWEEN 3 AND 500 "
        "AND maximum_feature_variants BETWEEN 1 AND maximum_trials "
        "AND maximum_model_variants BETWEEN 1 AND maximum_trials "
        "AND maximum_simulator_variants BETWEEN 1 AND maximum_trials",
        name="ck_research_experiment_budgets",
    ),
    CheckConstraint(
        "period_start <= period_end AND cardinality(permitted_families) > 0 "
        "AND cardinality(data_scope_identities) = cardinality(data_scope_hashes)",
        name="ck_research_experiment_scope",
    ),
    CheckConstraint(
        "length(universe_hash) = 64 AND length(parameter_space_hash) = 64 "
        "AND length(evaluation_policy_hash) = 64 "
        "AND length(cost_execution_hash) = 64 "
        "AND length(canonical_input_hash) = 64 "
        "AND length(canonical_result_hash) = 64",
        name="ck_research_experiment_hashes",
    ),
)
