        "source_type IN ('CANONICAL_BASELINE','SECURITIES_RESEARCH',"
        "'SECURITIES_SIMULATION','STRATEGY_LAB_TRAINING','STRATEGY_LAB_CANDIDATE',"
        "'STRATEGY_LAB_SHADOW','EXTERNAL_SIMULATOR','FIXTURE_VALIDATION')",
        name="ck_research_trial_source",
