# Real provider evidence is deliberately separate from financial and PAPER
# metadata.  The only retained market-data links point to the existing
# immutable Securities evidence and research tables.
real_securities_data_metadata = MetaData()
for _table_name, _primary_key in (
    ("securities_market_data_batch", "batch_id"),
    ("strategy_lab_feature_schema", "schema_id"),
    ("strategy_lab_dataset_snapshot", "dataset_id"),
    ("research_experiment_family", "experiment_id"),
    ("automated_candidate_search_run", "search_run_id"),
    ("operator_action", "action_id"),
):
    Table(
        _table_name,
        real_securities_data_metadata,
        Column(_primary_key, String(160), primary_key=True),
    )

