TRIGGER_DDL = """
CREATE OR REPLACE FUNCTION apex_reject_mutation() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    RAISE EXCEPTION 'immutable Apex row cannot be changed';
END;
$$;

CREATE OR REPLACE FUNCTION apex_guard_journal() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
    posting_count integer;
    debit_total numeric(38,18);
    credit_total numeric(38,18);
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF NEW.status <> 'PENDING' THEN
            RAISE EXCEPTION 'journal must begin pending';
        END IF;
        RETURN NEW;
    END IF;
    IF TG_OP = 'DELETE' THEN
        IF OLD.status = 'POSTED' THEN
            RAISE EXCEPTION 'posted journal is immutable';
        END IF;
        RETURN OLD;
    END IF;
    IF OLD.status <> 'PENDING' OR NEW.status <> 'POSTED'
       OR (to_jsonb(OLD) - 'status') <> (to_jsonb(NEW) - 'status') THEN
        RAISE EXCEPTION 'only a pending-to-posted transition is permitted';
    END IF;
    SELECT count(*),
           coalesce(sum(CASE WHEN side = 'DEBIT' THEN amount ELSE 0 END), 0),
           coalesce(sum(CASE WHEN side = 'CREDIT' THEN amount ELSE 0 END), 0)
      INTO posting_count, debit_total, credit_total
      FROM ledger_posting WHERE journal_id = OLD.journal_id;
    IF posting_count < 2 OR debit_total <> credit_total THEN
        RAISE EXCEPTION 'posted journal must balance exactly';
    END IF;
    RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION apex_guard_posting() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
    parent_status text;
    target_journal_id text;
BEGIN
    target_journal_id := CASE WHEN TG_OP = 'DELETE' THEN OLD.journal_id ELSE NEW.journal_id END;
    SELECT status INTO parent_status FROM ledger_journal WHERE journal_id = target_journal_id;
    IF parent_status = 'POSTED' THEN
        RAISE EXCEPTION 'postings of a posted journal are immutable';
    END IF;
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;

CREATE TRIGGER apex_guard_journal_trigger
BEFORE INSERT OR UPDATE OR DELETE ON ledger_journal
FOR EACH ROW EXECUTE FUNCTION apex_guard_journal();

CREATE TRIGGER apex_guard_posting_trigger
BEFORE INSERT OR UPDATE OR DELETE ON ledger_posting
FOR EACH ROW EXECUTE FUNCTION apex_guard_posting();
"""


