    def retained_market_dynamics_market(
        self, *, market_snapshot_id: str, maximum_observations: int
    ) -> MarketDynamicsMarketEvidence:
        """Load only independently event/series/rule-enriched quote history.

        A list or exact-market response can omit ``series_ticker``.  This method
        deliberately never fills that value from the newest row.  Each retained
        market snapshot must have its own exact event membership and event-series
        lineage, otherwise the domain feature stays ineligible.
        """

        if not 3 <= maximum_observations <= 50:
            raise ValueError("market dynamics observations must be between three and 50")
        latest = self.retained_market(market_snapshot_id)

        with self._session_factory() as session:
            rows = tuple(
                session.execute(
                    select(
                        normalized_market_snapshot,
                        raw_provider_response.c.received_at,
                    )
                    .select_from(
                        normalized_market_snapshot.join(
                            raw_provider_response,
                            raw_provider_response.c.raw_response_id
                            == normalized_market_snapshot.c.raw_response_id,
                        )
                    )
                    .where(
                        normalized_market_snapshot.c.provider == "KALSHI",
                        normalized_market_snapshot.c.provider_market_ticker
                        == latest.provider_market_ticker,
                    )
                    .order_by(
                        normalized_market_snapshot.c.observed_at.desc(),
                        normalized_market_snapshot.c.snapshot_id.desc(),
                    )
                    .limit(maximum_observations)
                ).mappings()
            )
            snapshot_ids = tuple(str(row["snapshot_id"]) for row in rows)
            lineage_rows = (
                tuple(
                    session.execute(
                        select(
                            event_market_relationship.c.market_snapshot_id,
                            event_market_relationship.c.provider_event_ticker,
                            event_market_relationship.c.market_rule_content_hash,
                            event_market_relationship.c.event_nested_rule_content_hash,
                            event_market_relationship.c.relationship_state,
                            normalized_event_snapshot.c.series_ticker,
                            normalized_event_snapshot.c.provider_event_ticker.label(
                                "event_snapshot_ticker"
                            ),
                        )
                        .select_from(
                            event_market_relationship.join(
                                normalized_event_snapshot,
                                normalized_event_snapshot.c.event_snapshot_id
                                == event_market_relationship.c.event_snapshot_id,
                            )
                        )
                        .where(event_market_relationship.c.market_snapshot_id.in_(snapshot_ids))
                    ).mappings()
                )
                if snapshot_ids
                else ()
            )
        lineage_by_snapshot: dict[str, tuple[str, str] | None] = {}
        for lineage in lineage_rows:
            snapshot_id = str(lineage["market_snapshot_id"])
            event_ticker = lineage["provider_event_ticker"]
            event_snapshot_ticker = lineage["event_snapshot_ticker"]
            series_ticker = lineage["series_ticker"]
            valid = (
                lineage["relationship_state"] == "EXACT"
                and isinstance(event_ticker, str)
                and bool(event_ticker)
                and event_snapshot_ticker == event_ticker
                and isinstance(series_ticker, str)
                and bool(series_ticker)
                and lineage["market_rule_content_hash"] is not None
                and lineage["market_rule_content_hash"] == lineage["event_nested_rule_content_hash"]
            )
            candidate = (str(event_ticker), str(series_ticker)) if valid else None
            previous = lineage_by_snapshot.get(snapshot_id, candidate)
            lineage_by_snapshot[snapshot_id] = candidate if previous == candidate else None

        def lineage_for(row: RowMapping) -> tuple[str | None, str | None]:
            value = lineage_by_snapshot.get(str(row["snapshot_id"]))
            return value if value is not None else (None, None)

        ordered = tuple(reversed(rows))
        observations = tuple(
            MarketDynamicsObservation(
                snapshot_id=str(row["snapshot_id"]),
                provider=PublicMarketProvider(str(row["provider"])),
                provider_market_ticker=str(row["provider_market_ticker"]),
                provider_event_ticker=lineage_for(row)[0],
                series_ticker=lineage_for(row)[1],
                observed_at=cast(datetime, row["observed_at"]),
                available_at=cast(datetime, row["received_at"]),
                close_at=cast(datetime | None, row["close_time"] or row["latest_expiration_time"]),
                status=cast(str | None, row["status"]),
                rule_content_hash=(
                    ContentHash(str(row["rule_content_hash"]))
                    if row["rule_content_hash"] is not None
                    else None
                ),
                yes_bid=(_domain_decimal(row["yes_bid"]) if row["yes_bid"] is not None else None),
                yes_ask=(_domain_decimal(row["yes_ask"]) if row["yes_ask"] is not None else None),
            )
            for row in ordered
        )
        latest_observation = observations[-1] if observations else None
        return MarketDynamicsMarketEvidence(
            market_snapshot_id=market_snapshot_id,
            provider=PublicMarketProvider(latest.provider),
            provider_market_ticker=latest.provider_market_ticker,
            provider_event_ticker=(
                latest_observation.provider_event_ticker if latest_observation else None
            ),
            series_ticker=latest_observation.series_ticker if latest_observation else None,
            active=latest.close_at > datetime.now(tz=UTC),
            observations=observations,
        )

