    def demo_financial_counts(self, campaign_id: str) -> dict[str, int]:
        """Return financial-row counts for the isolated strategy-shadow demo proof."""

        with self._session_factory() as session:

            def count(table: Table) -> int:
                return int(
                    session.scalar(
                        select(func.count())
                        .select_from(table)
                        .where(table.c.campaign_id == campaign_id)
                    )
                    or 0
                )

            return {
                "reservations": count(durable_risk_reservation),
                "orders": count(durable_order),
                "positions": count(position),
                "ledger_journals": count(ledger_journal),
            }

    def retain_demo_settlement_fact(
        self,
        *,
        campaign_id: str,
        settlement_fact_id_value: str,
        instrument_id: str,
        rule_content_hash: str,
        recorded_at: datetime,
    ) -> None:
        """Retain the deterministic demo's outcome without a financial operation."""

        raw_payload = f"demo-outcome:YES;instrument={instrument_id};rule_hash={rule_content_hash}"
        payload = {
            "campaign_id": campaign_id,
            "fixture_id": "strategy-shadow-demo-local-outcome-v1",
            "schema_version": "2",
            "source_id": "strategy-shadow-demo-local-outcome-source-v1",
            "instrument_id": instrument_id,
            "rule_version_id": "strategy-shadow-demo-local-rule-v1",
            "rule_content_hash": rule_content_hash,
            "resolution_source": "local-demo-retained-outcome",
            "classification": "YES",
            "settlement_value": Decimal(1),
            "settlement_value_text": "1",
            "determination_at": recorded_at - timedelta(seconds=1),
            "source_event_at": recorded_at - timedelta(seconds=1),
            "available_at": recorded_at,
            "raw_payload_hash": sha256(raw_payload.encode("utf-8")).hexdigest(),
            "raw_payload": raw_payload,
        }
        values = {
            "settlement_fact_id": settlement_fact_id_value,
            **payload,
            "void_term_content_hash": None,
            "canonical_evidence_hash": content_digest(payload),
            "canonical_payload_hash": content_digest({"demo_shadow_outcome": payload}),
            "created_at": recorded_at,
        }
        with self._session_factory() as session, session.begin():
            existing = session.scalar(
                select(settlement_fact.c.canonical_payload_hash).where(
                    settlement_fact.c.settlement_fact_id == settlement_fact_id_value
                )
            )
            if existing is None:
                session.execute(settlement_fact.insert().values(**values))
            elif str(existing) != str(values["canonical_payload_hash"]):
                raise AutopilotError("strategy-shadow demo settlement fact identity conflicts")

    def prediction(self, prediction_id: str) -> ShadowPrediction | None:
        with self._session_factory() as session:
            row = (
                session.execute(
                    select(shadow_prediction).where(
                        shadow_prediction.c.prediction_id == prediction_id
                    )
                )
                .mappings()
                .one_or_none()
            )
            return self._prediction_from_row(row) if row is not None else None

    def predictions(
        self,
        *,
        campaign_id: str | None = None,
        strategy_id: str | None = None,
        state: ShadowPredictionState | None = None,
        limit: int = 100,
    ) -> tuple[dict[str, object], ...]:
        with self._session_factory() as session:
            query = (
                select(shadow_prediction)
                .order_by(shadow_prediction.c.decision_at.desc())
                .limit(limit)
            )
            if campaign_id is not None:
                query = query.where(shadow_prediction.c.campaign_id == campaign_id)
            if strategy_id is not None:
                query = query.where(shadow_prediction.c.strategy_id == strategy_id)
            if state is not None:
                query = query.where(shadow_prediction.c.state == state.value)
            return tuple(dict(row) for row in session.execute(query).mappings())

